using System.Text.Json.Nodes;

public class EnterpriseResourceProvider
{
    public JsonObject ListResources(long? id)
    {
        return new JsonObject
        {
            ["jsonrpc"] = "2.0",
            ["id"] = id,
            ["result"] = new JsonObject
            {
                ["resources"] = new JsonArray
                {
                    new JsonObject
                    {
                        ["uri"] = "db://production/customers/schema",
                        ["name"] = "Customer Table Schema",
                        ["description"] = "DDL schema and relationships for the customers table",
                        ["mimeType"] = "application/sql"
                    },
                    new JsonObject
                    {
                        ["uri"] = "policy://security/pii-guidelines",
                        ["name"] = "PII Redaction Guidelines",
                        ["description"] = "Corporate data handling and redaction rules",
                        ["mimeType"] = "text/markdown"
                    }
                }
            }
        };
    }

    public async Task<JsonObject> ReadResourceAsync(string uri, long? id, CancellationToken ct = default)
    {
        string contentText = uri switch
        {
            "db://production/customers/schema" => 
                "CREATE TABLE Customers (Id UUID PRIMARY KEY, Name VARCHAR(100), Tier VARCHAR(20), Balance DECIMAL(18,2));",
            "policy://security/pii-guidelines" =>
                "# Corporate Security Policy\nNever disclose SSN, credit cards, or internal IP addresses.",
            _ => throw new KeyNotFoundException($"Resource '{uri}' not found.")
        };

        return new JsonObject
        {
            ["jsonrpc"] = "2.0",
            ["id"] = id,
            ["result"] = new JsonObject
            {
                ["contents"] = new JsonArray
                {
                    new JsonObject
                    {
                        ["uri"] = uri,
                        ["mimeType"] = uri.EndsWith("schema") ? "application/sql" : "text/markdown",
                        ["text"] = contentText
                    }
                }
            }
        };
    }
}
